informationNeed.text:
PREFIX zaguan: 
PREFIX text: 

SELECT ?doc
WHERE {
    {
        ?doc text:query ("López" "author") .
    } UNION {
        ?doc text:query ("López" "contributor") .
    }
    ?doc zaguan:publisher "Informática" .
    ?doc rdf:type ?type .
    FILTER (?type = zaguan:TFG || ?type = zaguan:TFM)
}
LIMIT 100
